// Quick sanity check of the hit-test math
function pointToSegmentDistance(px, py, ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) {
    const ex = px - ax;
    const ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx;
  const cy = ay + t * dy;
  const ex = px - cx;
  const ey = py - cy;
  return Math.sqrt(ex * ex + ey * ey);
}

// Point on segment → distance 0
console.assert(pointToSegmentDistance(5, 5, 0, 0, 10, 10) < 0.001, 'on-segment');

// Point perpendicular to segment midpoint
const d = pointToSegmentDistance(5, 0, 0, 0, 10, 0);
console.assert(d === 0, 'on horizontal segment');

// Point 3 units above horizontal segment
const d2 = pointToSegmentDistance(5, 3, 0, 0, 10, 0);
console.assert(Math.abs(d2 - 3) < 0.001, 'above segment');

// Point beyond segment end
const d3 = pointToSegmentDistance(15, 0, 0, 0, 10, 0);
console.assert(Math.abs(d3 - 5) < 0.001, 'beyond end');

// Degenerate segment (zero length)
const d4 = pointToSegmentDistance(3, 4, 0, 0, 0, 0);
console.assert(Math.abs(d4 - 5) < 0.001, 'degenerate');

console.log('All hit-test math checks pass');
EOF
