function netColor(netName) {
  const overrides = { 'VCC': 'hsl(0, 80%, 50%)', 'GND': 'hsl(220, 70%, 35%)', '3V3': 'hsl(30, 90%, 50%)' };
  const upper = netName.toUpperCase();
  if (overrides[upper]) return overrides[upper];
  let hash = 0;
  for (let i = 0; i < netName.length; i++) {
    hash = ((hash << 5) - hash + netName.charCodeAt(i)) | 0;
  }
  const hue = ((hash % 360) + 360) % 360;
  return `hsl(${hue}, 70%, 50%)`;
}

// Deterministic
console.assert(netColor('NET1') === netColor('NET1'), 'deterministic');

// Overrides
console.assert(netColor('VCC') === 'hsl(0, 80%, 50%)', 'VCC override');
console.assert(netColor('GND') === 'hsl(220, 70%, 35%)', 'GND override');
console.assert(netColor('gnd') === 'hsl(220, 70%, 35%)', 'GND case insensitive');

// Different nets produce different colors
const c1 = netColor('SDA');
const c2 = netColor('SCL');
const c3 = netColor('CLK');
console.assert(c1 !== c2, 'SDA !== SCL');
console.assert(c2 !== c3, 'SCL !== CLK');

console.log('OK:', c1, c2, c3);
EOF
